function stereoParams = myStereoCameraCalibrator(folder1,folder2,square_size,show)
% stereoParams = myStereoCameraCalibrator(folder1, folder2, square_size, show)
% Stereo calibration from checkerboard pairs in folder1 (cam1) and folder2
% (cam2), paired by sorted file name. square_size in mm. show (default true)
% plots reprojection errors and board positions and prints parameter errors.
% Adapted from code generated by the Stereo Camera Calibrator app (2022).

% Define images to process
imageFileNames1 = listImageFiles(folder1);
imageFileNames2 = listImageFiles(folder2);
if numel(imageFileNames1) ~= numel(imageFileNames2)
    error('cam1 has %i images but cam2 has %i', numel(imageFileNames1), numel(imageFileNames2))
end

% Detect checkerboards in images. Returns vertex image coordinates in pixels, in
% (npoints x 2xy x nimages x 2cameras) matrix
[imagePoints, boardSize, pairsDetected] = detectCheckerboardPoints(imageFileNames1, imageFileNames2);
if ~all(pairsDetected)
    warning('Checkerboard not found in image pair(s): %s', strjoin(imageFileNames1(~pairsDetected), ', '))
end

% Generate world coordinates of the checkerboard keypoints
worldPoints = generateCheckerboardPoints(boardSize, square_size);

% Read one of the images from the first stereo pair
I1 = imread(imageFileNames1{1});
[mrows, ncols, ~] = size(I1);

% Calibrate the camera
[stereoParams, ~, estimationErrors] = estimateCameraParameters(imagePoints, worldPoints, ...
    'EstimateSkew', false, 'EstimateTangentialDistortion', false, ...
    'NumRadialDistortionCoefficients', 2, 'WorldUnits', 'millimeters', ...
    'InitialIntrinsicMatrix', [], 'InitialRadialDistortion', [], ...
    'ImageSize', [mrows, ncols]);

if ~exist('show', 'var') || show
    % View reprojection errors
    figure('Name','Checkerboard: reprojection error'); showReprojectionErrors(stereoParams); drawnow

    % Visualize pattern locations
    figure('Name','Checkerboard: extrinsics'); showExtrinsics(stereoParams, 'CameraCentric'); drawnow

    % Display parameter estimation errors
    displayErrors(estimationErrors, stereoParams);
end


% See additional examples of how to use the calibration data.  At the prompt type:
% showdemo('StereoCalibrationAndSceneReconstructionExample')
% showdemo('DepthEstimationFromStereoVideoExample')
